#include "protocol.hpp"
#include "core/binary.hpp"
namespace crackhood {
static void header(Writer&w,uint64_t id){w.number(0x484b5243,4);w.number(1,4);w.number(0,4);w.number(id,8);}
static std::vector<std::byte> finish(Writer&w){if(w.bytes.size()>1048576)throw std::runtime_error("frame too large");auto size=w.bytes.size();for(unsigned i=0;i<4;++i)w.bytes[8+i]=static_cast<std::byte>((size>>(8*i))&255);return std::move(w.bytes);}
static uint64_t check_header(Reader&r){if(r.bytes.size()>1048576||r.number(4)!=0x484b5243||r.number(4)!=1)throw std::runtime_error("invalid frame version");if(r.number(4)!=r.bytes.size())throw std::runtime_error("invalid frame length");return r.number(8);}
static void payload(Writer&w,std::span<const std::byte>b){if(b.size()>1048576)throw std::runtime_error("payload too large");w.number(b.size(),4);w.bytes.insert(w.bytes.end(),b.begin(),b.end());}
static std::vector<std::byte> payload(Reader&r){auto n=r.number(4);if(n>1048576||n!=r.bytes.size()-r.offset)throw std::runtime_error("invalid payload length");return {r.bytes.begin()+r.offset,r.bytes.end()};}
Result<Request> decode_request(std::span<const std::byte>b){try{Reader r{b};Request q;q.id=check_header(r);q.console.value=r.text();q.operation=r.text();q.path.value=r.text();q.payload=payload(r);return q;}catch(const std::exception&e){return Error{ErrorCode::Protocol,e.what()};}}
Result<std::vector<std::byte>> encode_request(const Request&q){try{if(q.version!=1)throw std::runtime_error("invalid version");Writer w;header(w,q.id);w.text(q.console.value);w.text(q.operation);w.text(q.path.value);payload(w,q.payload);return finish(w);}catch(const std::exception&e){return Error{ErrorCode::Protocol,e.what()};}}
Result<Response> decode_response(std::span<const std::byte>b){try{Reader r{b};Response q;q.id=check_header(r);auto flag=r.number(1);if(flag==1){auto code=r.number(4);if(code>static_cast<uint32_t>(ErrorCode::Uncertain))throw std::runtime_error("invalid error code");Error e{static_cast<ErrorCode>(code),{},static_cast<int32_t>(r.number(4))};e.message=r.text();if(r.offset!=b.size())throw std::runtime_error("trailing error data");q.result=e;}else if(flag==0)q.result=payload(r);else throw std::runtime_error("invalid response tag");return q;}catch(const std::exception&e){return Error{ErrorCode::Protocol,e.what()};}}
Result<std::vector<std::byte>> encode_response(const Response&q){try{Writer w;header(w,q.id);if(auto e=std::get_if<Error>(&q.result)){w.number(1,1);w.number(static_cast<uint32_t>(e->code),4);w.number(static_cast<uint32_t>(e->native_code),4);w.text(e->message);}else{w.number(0,1);payload(w,std::get<std::vector<std::byte>>(q.result));}return finish(w);}catch(const std::exception&e){return Error{ErrorCode::Protocol,e.what()};}}
std::vector<std::byte> encode_entries(const std::vector<Entry>&entries){Writer w;if(entries.size()>65536)throw std::runtime_error("too many entries");w.number(entries.size(),4);for(auto&e:entries){w.text(e.name);w.number(e.directory,1);w.number(e.size,8);w.number(e.modified_filetime,8);w.number(e.attributes,4);if(w.bytes.size()>1048500)throw std::runtime_error("directory page too large");}return std::move(w.bytes);}
Result<std::vector<Entry>> decode_entries(std::span<const std::byte>b){try{if(b.size()>1048576)throw std::runtime_error("entries too large");Reader r{b};auto count=r.number(4);if(count>65536||count>(b.size()-r.offset)/25)throw std::runtime_error("invalid entry count");std::vector<Entry>entries;entries.reserve(static_cast<size_t>(count));while(count--){Entry e;e.name=r.text();auto dir=r.number(1);if(dir>1)throw std::runtime_error("invalid directory flag");e.directory=dir!=0;e.size=r.number(8);e.modified_filetime=r.number(8);e.attributes=static_cast<uint32_t>(r.number(4));entries.push_back(std::move(e));}if(r.offset!=b.size())throw std::runtime_error("trailing entry data");return entries;}catch(const std::exception&e){return Error{ErrorCode::Protocol,e.what()};}}
}
